import Complex64 = require( '@stdlib/complex/float32/ctor' );
import cfloornf = require( './index' );


// TESTS //

// The function returns a single-precision complex floating-point number...
{
	cfloornf( new Complex64( 1.0, 2.0 ), -2 ); // $ExpectType Complex64
}

// The compiler throws an error if the first argument of the function is provided a value other than a complex number...
{
	cfloornf( 3, -2 ); // $ExpectError
	cfloornf( true, -2 ); // $ExpectError
	cfloornf( false, -2 ); // $ExpectError
	cfloornf( null, -2 ); // $ExpectError
	cfloornf( undefined, -2 ); // $ExpectError
	cfloornf( '5', -2 ); // $ExpectError
	cfloornf( [], -2 ); // $ExpectError
	cfloornf( {}, -2 ); // $ExpectError
	cfloornf( ( x: number ): number => x, -2 ); // $ExpectError
}

// The compiler throws an error if the second argument of the function is provided a value other than a number...
{
	cfloornf( new Complex64( 1.0, 2.0 ), 3, -2 ); // $ExpectError
	cfloornf( new Complex64( 1.0, 2.0 ), true, -2 ); // $ExpectError
	cfloornf( new Complex64( 1.0, 2.0 ), false, -2 ); // $ExpectError
	cfloornf( new Complex64( 1.0, 2.0 ), null, -2 ); // $ExpectError
	cfloornf( new Complex64( 1.0, 2.0 ), undefined, -2 ); // $ExpectError
	cfloornf( new Complex64( 1.0, 2.0 ), '5', -2 ); // $ExpectError
	cfloornf( new Complex64( 1.0, 2.0 ), [], -2 ); // $ExpectError
	cfloornf( new Complex64( 1.0, 2.0 ), {}, -2 ); // $ExpectError
	cfloornf( new Complex64( 1.0, 2.0 ), ( x: number ): number => x, -2 ); // $ExpectError
}

// The compiler throws an error if the function is provided insufficient arguments...
{
	cfloornf(); // $ExpectError
	cfloornf( 2 ); // $ExpectError
}
